// Annales officielles 2026, sujet test inspecteur et QCM d'entraînement inédit (dossier 05).
// Format : id, t (thème), q, o (4 propositions), a (index 0-3 de la bonne réponse),
// e (explication), s (source), d:1 = douteuse, act:1 = actualité datée.
BANK.push(
// ---------- QCM officiel inspecteur 2026 ----------
{id:"i26-01",t:"admin",q:"Quelle est la définition du principe d'universalité budgétaire ?",o:["Chaque recette est affectée à une dépense","L'autorisation budgétaire donnée à l'exécutif n'est valable que pour un an","Le budget décrit, pour la durée de l'exercice, l'ensemble des recettes qui financent l'ensemble des dépenses","Le budget doit être accompagné de l'ensemble des pièces comptables justificatives"],a:2,e:"Universalité = non-compensation et non-affectation : toutes les recettes financent toutes les dépenses. La 2e proposition décrit l'annualité.",x:"Les principes budgétaires classiques sont l'annualité, l'unité, l'universalité et la spécialité ; la LOLF y ajoute la sincérité. Les fonds de concours et les comptes d'affectation spéciale font exception à la non-affectation.",u:["https://www.vie-publique.fr/fiches/21823-quels-sont-les-grands-principes-budgetaires","https://fr.wikipedia.org/wiki/Principe_d'universalit%C3%A9_budg%C3%A9taire"],s:"QCM inspecteur 2026, Q1"},
{id:"i26-02",t:"admin",q:"Selon l'article 24 de la Constitution, quel est l'un des rôles du Sénat ?",o:["Représenter la France auprès des collectivités territoriales étrangères","Représenter la position du Gouvernement","Représenter les collectivités territoriales de la République","Représenter les seules collectivités territoriales métropolitaines"],a:2,e:"Art. 24 : le Sénat assure la représentation des collectivités territoriales de la République (outre-mer compris).",x:"Le Sénat compte 348 sénateurs élus au suffrage universel indirect pour 6 ans et renouvelés par moitié tous les 3 ans. L'article 24 prévoit aussi la représentation des Français établis hors de France.",u:["https://www.vie-publique.fr/fiches/19584-quest-ce-que-le-senat","https://fr.wikipedia.org/wiki/S%C3%A9nat_(France)"],s:"QCM inspecteur 2026, Q2"},
{id:"i26-03",t:"admin",q:"« Un agent public doit garder confidentielles les informations personnelles relatives aux usagers dont il a eu connaissance dans l'exercice de ses fonctions. » À quelle obligation cela renvoie-t-il ?",o:["L'impartialité","La neutralité","L'obéissance hiérarchique","Le secret professionnel"],a:3,e:"Le secret professionnel protège les usagers (sanction pénale) ; la discrétion professionnelle protège l'administration.",x:"Sa violation est punie d'un an d'emprisonnement et de 15 000 € d'amende (art. 226-13 du Code pénal). Ne pas confondre avec la discrétion professionnelle, qui protège l'administration.",u:["https://www.vie-publique.fr/fiches/20259-quels-sont-les-devoirs-des-fonctionnaires","https://fr.wikipedia.org/wiki/Secret_professionnel_en_droit_fran%C3%A7ais"],s:"QCM inspecteur 2026, Q3"},
{id:"i26-04",t:"admin",q:"Le Pacte de stabilité et de croissance (1997) plafonne le déficit public des États membres à quelle part du PIB ?",o:["1 %","3 %","5 %","10 %"],a:1,e:"Critères de Maastricht repris par le Pacte : déficit ≤ 3 % du PIB, dette ≤ 60 % du PIB.",x:"Adopté au Conseil européen d'Amsterdam en juin 1997, le Pacte a été réformé en 2005, en 2011 (« six-pack ») et en 2024. Un dépassement du seuil peut conduire à une procédure pour déficit excessif, ouverte contre la France en juillet 2024.",u:["https://www.vie-publique.fr/fiches/21801-quest-ce-que-le-pacte-de-stabilite-et-de-croissance-psc","https://fr.wikipedia.org/wiki/Pacte_de_stabilit%C3%A9_et_de_croissance"],s:"QCM inspecteur 2026, Q4"},
{id:"i26-05",t:"admin",q:"Qu'est-ce que la fongibilité asymétrique définie par la LOLF ?",o:["En cas d'insuffisance, des crédits inutilisés d'autres programmes peuvent être transférés sur les dépenses de personnel","La fongibilité asymétrique est interdite depuis la LOLF","Les crédits de personnel peuvent être utilisés pour d'autres natures de dépenses","Les crédits d'un programme peuvent être utilisés sur tout autre programme en cas d'insuffisance justifiée auprès du Parlement"],a:2,e:"Dans un programme, les crédits du titre 2 (personnel) peuvent financer d'autres dépenses, jamais l'inverse.",x:"Les crédits de personnel (titre 2) sont plafonnés dans chaque programme ; les emplois font l'objet d'un plafond par ministère, exprimé en ETPT. Le gestionnaire peut redéployer des crédits de personnel vers le fonctionnement ou l'investissement, jamais l'inverse.",u:["https://www.vie-publique.fr/fiches/21876-lolf-les-prerogatives-des-gestionnaires-dans-lexecution-des-depenses","https://fr.wikipedia.org/wiki/Fongibilit%C3%A9_asym%C3%A9trique"],s:"QCM inspecteur 2026, Q5"},
{id:"i26-06",t:"admin",q:"Quels sont les quatre principes fondamentaux de la République française (article 1er) ?",o:["Démocratie, liberté, laïcité, fraternité","Indivisibilité, laïcité, démocratie, social","Indivisibilité, laïcité, liberté, tolérance","Liberté, égalité, fraternité, laïcité"],a:1,e:"Art. 1er : République indivisible, laïque, démocratique et sociale. « Liberté, Égalité, Fraternité » est la devise (art. 2).",x:"L'article 1er ajoute que la République assure l'égalité devant la loi de tous les citoyens sans distinction d'origine, de race ou de religion, et que son organisation est décentralisée (depuis 2003). L'article 2 fixe la langue, l'emblème, l'hymne, la devise et le principe de la République.",u:["https://www.vie-publique.fr/fiches/19562-quels-sont-les-principes-fondamentaux-de-la-republique-francaise","https://fr.wikipedia.org/wiki/Article_premier_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"QCM inspecteur 2026, Q6"},
{id:"i26-07",t:"admin",q:"Le budget de l'État est structuré en trois niveaux. À quoi correspondent les missions ?",o:["À la destination des crédits","Au budget accordé à chaque ministère","Au cadre de mise en œuvre des dépenses d'investissement de l'État","Aux grandes politiques de l'État"],a:3,e:"La mission regroupe les programmes concourant à une politique publique ; elle peut être interministérielle. C'est l'unité de vote.",x:"La LOLF organise les crédits en missions (unité de vote), programmes (unité de spécialité, confiés à un responsable de programme) et actions. Une mission peut être interministérielle, comme « Recherche et enseignement supérieur ».",u:["https://www.vie-publique.fr/fiches/21875-comment-les-depenses-sont-elles-presentees-dans-le-budget-de-letat","https://fr.wikipedia.org/wiki/Loi_organique_relative_aux_lois_de_finances"],s:"QCM inspecteur 2026, Q7"},
{id:"i26-08",t:"admin",q:"Quelle est la durée du mandat d'un maire ?",o:["4 ans","5 ans","6 ans","7 ans"],a:2,e:"Le maire est élu par le conseil municipal, lui-même élu pour 6 ans.",x:"Le maire est élu par le conseil municipal lors de sa première séance, au scrutin secret. Il est à la fois agent de l'État (état civil, officier de police judiciaire) et exécutif de la commune.",u:["https://www.vie-publique.fr/fiches/19617-les-fonctions-les-pouvoirs-dun-maire","https://fr.wikipedia.org/wiki/Maire_(France)"],s:"QCM inspecteur 2026, Q8"},
{id:"i26-09",t:"admin",q:"La libre administration des collectivités territoriales est :",o:["Un principe constitutionnel","Un principe jurisprudentiel","Un principe législatif","Un principe réglementaire"],a:0,e:"Article 72 de la Constitution : les collectivités s'administrent librement par des conseils élus.",x:"Elle s'exerce « dans les conditions prévues par la loi » (art. 72 al. 3) : c'est la loi qui détermine les principes fondamentaux de la libre administration des collectivités, de leurs compétences et de leurs ressources (art. 34).",u:["https://www.vie-publique.fr/fiches/20157-en-quoi-consiste-la-libre-administration-des-collectivites-locales","https://fr.wikipedia.org/wiki/Principe_de_libre_administration_des_collectivit%C3%A9s_territoriales_en_France"],s:"QCM inspecteur 2026, Q9"},
{id:"i26-10",t:"admin",q:"À l'été 2023, la dette publique de la France a dépassé 3 000 milliards d'euros. À quoi correspond cette dette ?",o:["À l'ensemble des emprunts contractés par les collectivités territoriales","À l'ensemble des emprunts contractés par l'État","À l'ensemble des emprunts contractés par l'État, la Sécurité sociale, les ODAC et les collectivités territoriales","Au solde annuel négatif du budget des administrations publiques"],a:2,e:"La dette « au sens de Maastricht » couvre toutes les administrations publiques. Le solde annuel négatif est le déficit (un flux).",x:"Elle est mesurée en valeur nominale et brute, sans déduire les actifs, selon les règles européennes. Les ODAC sont les organismes divers d'administration centrale (universités, agences, etc.).",u:["https://www.vie-publique.fr/questions-reponses/304693-dette-publique-de-la-france-lessentiel-en-6-questions","https://fr.wikipedia.org/wiki/Dette_publique_de_la_France"],s:"QCM inspecteur 2026, Q10"},
{id:"i26-11",t:"ue",q:"Sur quelles libertés repose le marché unique européen ?",o:["Liberté d'expression, de religion, de vivre à l'abri du besoin et de la peur","Liberté d'opinion, d'expression, de réunion, de culte, syndicale","Liberté, égalité, fraternité","Libre circulation des biens, des personnes, des services et des capitaux"],a:3,e:"Les quatre libertés du marché intérieur (Acte unique, marché intérieur au 1er janvier 1993).",x:"Le marché intérieur s'étend aussi à l'Islande, au Liechtenstein et à la Norvège par l'Espace économique européen (EEE).",u:["https://www.vie-publique.fr/fiches/20404-quest-ce-que-le-marche-interieur","https://fr.wikipedia.org/wiki/Quatre_libert%C3%A9s_(Union_europ%C3%A9enne)"],s:"QCM inspecteur 2026, Q11"},
{id:"i26-12",t:"ue",q:"Quel est le rôle du Parlement européen dans l'adoption du cadre financier pluriannuel ?",o:["Il doit approuver le budget","Il fait la première proposition sur le montant","Il n'a qu'un rôle consultatif","Il n'a pas de rôle budgétaire"],a:0,e:"Le CFP est adopté par le Conseil à l'unanimité après approbation du Parlement européen (art. 312 TFUE).",x:"Le CFP fixe pour au moins cinq ans (en pratique sept) les plafonds annuels de dépenses par grande rubrique. Le Parlement l'approuve à la majorité des membres qui le composent, sans pouvoir l'amender.",u:["https://www.vie-publique.fr/fiches/20379-quest-ce-que-le-cadre-financier-pluriannuel-de-lunion-europeenne","https://fr.wikipedia.org/wiki/Budget_de_l'Union_europ%C3%A9enne"],s:"QCM inspecteur 2026, Q12"},
{id:"i26-13",t:"ue",q:"Quel État membre est le plus grand contributeur au budget de l'Union européenne ?",o:["L'Allemagne","L'Espagne","La France","L'Italie"],a:0,e:"L'Allemagne est première, la France deuxième.",x:"L'Allemagne, la France et l'Italie sont les trois premiers contributeurs bruts. En France, la contribution est versée par un prélèvement sur les recettes de l'État.",u:["https://www.vie-publique.fr/fiches/20380-comment-la-france-participe-t-elle-au-financement-de-lue","https://fr.wikipedia.org/wiki/Budget_de_l'Union_europ%C3%A9enne"],s:"QCM inspecteur 2026, Q13"},
{id:"i26-14",t:"ue",q:"Lequel de ces critères est une condition d'adhésion à l'Union européenne ?",o:["Adhérer à la zone euro","Avoir une dette publique inférieure à 60 % du PIB","Être une République","Respecter des droits fondamentaux comme la démocratie ou la protection des minorités"],a:3,e:"Critères de Copenhague (1993) : institutions démocratiques, État de droit, droits de l'homme, protection des minorités, économie de marché, reprise de l'acquis. L'euro n'est pas une condition.",x:"Les critères ont été fixés au Conseil européen de Copenhague en juin 1993. Ils sont politiques (démocratie, État de droit, droits de l'homme, minorités), économiques (économie de marché viable) et juridiques (reprise de l'acquis).",u:["https://www.vie-publique.fr/fiches/20366-quelles-sont-les-conditions-et-les-modalites-dadhesion-lue","https://fr.wikipedia.org/wiki/Crit%C3%A8res_de_Copenhague"],s:"QCM inspecteur 2026, Q14"},
{id:"i26-15",t:"ue",q:"En quelle année a été signé le traité de Lisbonne ?",o:["1957","1992","2001","2007"],a:3,e:"Signé le 13 décembre 2007, en vigueur le 1er décembre 2009.",x:"Il reprend l'essentiel du traité constitutionnel rejeté en 2005, sous la forme de deux traités modifiés : le TUE et le TFUE (ancien traité CE). Il supprime la structure en trois piliers.",u:["https://www.vie-publique.fr/fiches/20315-quest-ce-que-le-traite-de-lisbonne","https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"QCM inspecteur 2026, Q15"},
{id:"i26-16",t:"ue",q:"Quelle est la portée des règlements de l'Union européenne ?",o:["Ils nécessitent une transposition en droit national","Ils s'appliquent uniquement aux États qui les acceptent","Ils sont directement applicables dans tous les États membres","Ce sont de simples recommandations"],a:2,e:"Le règlement est obligatoire dans tous ses éléments et directement applicable. C'est la directive qui doit être transposée.",x:"Art. 288 TFUE : le règlement a une portée générale, il est obligatoire dans tous ses éléments et directement applicable dans tout État membre. Exemple : le RGPD, applicable depuis le 25 mai 2018 sans transposition.",u:["https://www.vie-publique.fr/fiches/20370-actes-juridiques-de-lue-quest-ce-quun-reglement","https://fr.wikipedia.org/wiki/R%C3%A8glement_de_l'Union_europ%C3%A9enne"],s:"QCM inspecteur 2026, Q16"},
{id:"i26-17",t:"ue",q:"Quelle mesure fiscale issue de l'OCDE est entrée en vigueur dans l'UE en 2024 pour lutter contre l'évasion fiscale ?",o:["Un impôt minimum de 15 % sur les multinationales","La suppression des paradis fiscaux en Europe","La taxe numérique européenne","Le renforcement de la TVA intracommunautaire"],a:0,e:"Directive « Pilier 2 » : imposition minimale effective de 15 % des grands groupes (CA ≥ 750 M€).",x:"La directive (UE) 2022/2523 du 15 décembre 2022 (date rectifiée au JOUE) met en œuvre l'accord conclu en 2021 au sein du Cadre inclusif OCDE/G20. Si un groupe est imposé à moins de 15 % dans un pays, un impôt complémentaire est dû.",u:["https://fr.wikipedia.org/wiki/Taux_d'imposition_mondial_minimum"],s:"QCM inspecteur 2026, Q17"},
{id:"i26-18",t:"ue",q:"Quel État membre présidait le Conseil de l'Union européenne depuis le 1er juillet 2025 ?",o:["Allemagne","Belgique","Danemark","Pologne"],a:2,e:"Pologne (1er semestre 2025), Danemark (2nd semestre 2025), Chypre (1er semestre 2026), Irlande (2nd semestre 2026).",x:"Chaque État préside six mois, au sein de trios qui fixent un programme commun sur 18 mois. Le Danemark avait déjà présidé le Conseil au premier semestre 2012.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_danoise_du_Conseil_de_l'Union_europ%C3%A9enne_en_2025","https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l'Union_europ%C3%A9enne"],s:"QCM inspecteur 2026, Q18",act:1},
{id:"i26-19",t:"ue",q:"Quelle institution veille à la bonne application du droit de l'Union par tous les États membres ?",o:["La Commission européenne","Le Conseil de l'Europe","La Cour de justice de l'Union européenne","La Cour européenne des droits de l'homme"],a:0,e:"La Commission est « gardienne des traités » : elle engage les recours en manquement. La CJUE juge, sur saisine.",x:"Le recours en manquement (art. 258 TFUE) est précédé d'une phase précontentieuse : lettre de mise en demeure, puis avis motivé. Si l'État ne se conforme pas à l'arrêt, la Commission peut demander des sanctions financières (art. 260 TFUE).",u:["https://www.vie-publique.fr/fiches/20332-quel-est-le-role-de-la-commission-europeenne","https://fr.wikipedia.org/wiki/Recours_en_manquement"],s:"QCM inspecteur 2026, Q19"},
{id:"i26-20",t:"ue",q:"Qui a été élu(e) président(e) du Parlement européen en janvier 2022 et réélu(e) en juillet 2024 ?",o:["Nicole Fontaine","Roberta Metsola","David Sassoli","Martin Schulz"],a:1,e:"Roberta Metsola (Malte) a succédé à David Sassoli, décédé en janvier 2022.",x:"Maltaise, elle est la troisième femme à présider le Parlement européen élu, après Simone Veil (1979) et Nicole Fontaine (1999). Le président est élu pour deux ans et demi, renouvelables.",u:["https://fr.wikipedia.org/wiki/Roberta_Metsola","https://fr.wikipedia.org/wiki/Pr%C3%A9sident_du_Parlement_europ%C3%A9en"],s:"QCM inspecteur 2026, Q20"},
{id:"i26-21",t:"num",q:"Quel est le rôle principal d'un pare-feu informatique ?",o:["Bloquer les publicités intrusives","Filtrer et sécuriser les connexions réseau","Optimiser la vitesse de connexion","Supprimer automatiquement les virus"],a:1,e:"Le pare-feu filtre les flux entrants et sortants ; c'est l'antivirus qui supprime les logiciels malveillants.",x:"Le pare-feu applique des règles (adresses, ports, protocoles) pour autoriser ou bloquer le trafic. Il complète l'antivirus sans le remplacer.",u:["https://fr.wikipedia.org/wiki/Pare-feu_(informatique)"],s:"QCM inspecteur 2026, Q21"},
{id:"i26-22",t:"num",q:"Sur l'open data (données ouvertes), trouvez l'intrus.",o:["L'open data offre la possibilité d'accéder à des statistiques médicales","L'open data permet d'utiliser des données protégées par des droits d'auteur","L'open data permet de consulter des données librement accessibles","L'open data peut être d'origine publique ou privée"],a:1,e:"Les données protégées par le droit d'auteur ou personnelles ne relèvent pas de l'open data.",x:"En France, la loi pour une République numérique (2016) pose l'ouverture par défaut des données publiques, publiées notamment sur data.gouv.fr. Les données personnelles doivent être anonymisées avant toute ouverture.",u:["https://fr.wikipedia.org/wiki/Donn%C3%A9es_ouvertes"],s:"QCM inspecteur 2026, Q22"},
{id:"i26-23",t:"num",q:"Qu'est-ce que l'illectronisme ?",o:["L'incapacité à utiliser le numérique faute de couverture réseau","L'incapacité à utiliser le numérique par manque de connaissance de son fonctionnement","La facilité à utiliser le numérique grâce à une très bonne connaissance","Les conséquences d'une surexposition aux écrans dès l'enfance"],a:1,e:"Illectronisme = illettrisme numérique, par manque de compétences (environ un Français sur six).",x:"Selon l'Insee (2019), 17 % de la population était concernée, faute d'usage d'Internet ou de compétences de base. Le mot est formé sur le modèle d'« illettrisme ».",u:["https://www.insee.fr/fr/statistiques/4241397","https://fr.wikipedia.org/wiki/Illectronisme"],s:"QCM inspecteur 2026, Q23"},
{id:"i26-24",t:"num",q:"D'où provient la majorité de l'empreinte carbone du numérique en France ?",o:["Des équipements (smartphones, ordinateurs, objets connectés)","Des centres de données","Des cryptoactifs","Des réseaux fixes et mobiles"],a:0,e:"Les équipements pèsent le plus : 79 % dans l'étude ADEME-Arcep de 2020, environ 50 % dans sa mise à jour, devant les centres de données (46 %) et les réseaux.",x:"La fabrication des terminaux concentre l'essentiel de leur impact : allonger leur durée de vie est le premier levier de sobriété numérique.",u:["https://fr.wikipedia.org/wiki/Impact_environnemental_du_num%C3%A9rique"],s:"QCM inspecteur 2026, Q24"},
{id:"i26-25",t:"num",q:"Quel est le principal objectif de la loi « Informatique et Libertés » ?",o:["Encadrer l'utilisation des données personnelles","Faciliter les échanges de données personnelles entre sites","Interdire les sites de commerce en ligne","Obliger les citoyens à s'inscrire sur une plateforme nationale"],a:0,e:"Loi du 6 janvier 1978, qui a créé la CNIL.",x:"Elle a été adoptée après l'affaire SAFARI (projet d'interconnexion de fichiers administratifs révélé en 1974). Elle a été réécrite en 2018 pour s'articuler avec le RGPD.",u:["https://www.cnil.fr/fr/le-cadre-national/la-loi-informatique-et-libertes","https://fr.wikipedia.org/wiki/Loi_informatique_et_libert%C3%A9s"],s:"QCM inspecteur 2026, Q25"},
{id:"i26-26",t:"num",q:"Quelle est la différence entre HTTP et HTTPS ?",o:["Il n'y en a aucune","HTTP est plus rapide","HTTPS est plus rapide","HTTPS est sécurisé"],a:3,e:"HTTPS chiffre les échanges (TLS) ; le « S » signifie Secure.",x:"Le chiffrement repose sur le protocole TLS (successeur de SSL), signalé par un cadenas. HTTPS protège la confidentialité des échanges, pas l'honnêteté du site : une page d'hameçonnage peut être en HTTPS.",u:["https://fr.wikipedia.org/wiki/Hypertext_Transfer_Protocol_Secure"],s:"QCM inspecteur 2026, Q26"},
{id:"i26-27",t:"num",q:"Qu'est-ce qu'un flux RSS ?",o:["Une messagerie pour échanger des données sensibles","Une revue informatique spécialisée","Un moyen de communication entre serveurs","Un système de diffusion de contenus fréquemment mis à jour sur un site"],a:3,e:"Le flux RSS diffuse automatiquement les nouveaux contenus d'un site.",x:"RSS signifie Really Simple Syndication. Un agrégateur (lecteur de flux) récupère les nouveaux contenus sans qu'il soit nécessaire de visiter le site.",u:["https://fr.wikipedia.org/wiki/RSS"],s:"QCM inspecteur 2026, Q27"},
{id:"i26-28",t:"num",q:"Qu'est-ce que le droit à la déconnexion ?",o:["Le droit de ne pas être connecté aux outils professionnels en dehors de ses horaires de travail","Le droit de se déconnecter de temps en temps sur son lieu de travail","Le droit de se déconnecter une heure par jour au travail","Le droit de travailler sans connexion Internet"],a:0,e:"Créé par la loi Travail de 2016 (applicable en 2017).",x:"Il figure à l'article L. 2242-17 du Code du travail : il fait l'objet d'une négociation dans les entreprises d'au moins 50 salariés ; à défaut d'accord, l'employeur élabore une charte.",u:["https://fr.wikipedia.org/wiki/Droit_%C3%A0_la_d%C3%A9connexion"],s:"QCM inspecteur 2026, Q28"},
{id:"i26-29",t:"num",q:"Qu'est-ce que la blockchain (« chaîne de blocs ») ?",o:["Un environnement dédié aux jeux en ligne","Une technologie de stockage et de transmission d'informations, décentralisée, qui valide et sécurise les échanges","Un réseau centralisé utilisé par les États pour sécuriser les transactions monétaires","Un système de protection contre les cyberattaques dans une entreprise"],a:1,e:"Registre distribué, sans tiers de confiance central.",x:"Chaque bloc contient l'empreinte (hachage) du précédent, ce qui rend détectable toute modification a posteriori. Le bitcoin (2009) en a été la première application.",u:["https://fr.wikipedia.org/wiki/Blockchain"],s:"QCM inspecteur 2026, Q29"},
{id:"i26-30",t:"num",q:"Qu'est-ce que l'exploration de données (« data mining ») ?",o:["La modification de données pour les rendre accessibles sur Internet","La recherche de données libres de droits","L'exploitation et l'analyse de grands ensembles de données","L'ouverture d'un dossier dans l'explorateur de fichiers"],a:2,e:"Data mining : extraire des tendances de grands volumes de données.",x:"Il s'appuie sur des méthodes statistiques et d'apprentissage automatique. La DGFiP y recourt depuis 2014 pour mieux cibler les contrôles fiscaux.",u:["https://fr.wikipedia.org/wiki/Exploration_de_donn%C3%A9es"],s:"QCM inspecteur 2026, Q30"},
{id:"i26-31",t:"log",q:"Quel est le mot manquant ? Cailloux – Pierres – Roches – ???",o:["Diamant","Granite","Paillage","Rubis"],a:1,e:"DOUTEUSE. La grille publique donne Granite. Mais la logique du nombre de lettres (8, 7, 6, puis 5) désigne Rubis. Question exclue des examens et du score.",s:"QCM inspecteur 2026, Q31",d:1},
{id:"i26-32",t:"log",q:"Des plaques sont facturées selon chaque lettre du nom. MARC paye 36 €, PUSSI 42 €, MARCEL 58 €, SUPINS 52 €, MARCO 45 €. Combien paiera NOËL ?",o:["38 €","40 €","41 €","46 €"],a:2,e:"MARCO − MARC : O = 9. MARCEL − MARC : E + L = 22. SUPINS − PUSSI : N = 10. NOËL = 10 + 9 + 22 = 41 €.",s:"QCM inspecteur 2026, Q32"},
{id:"i26-34",t:"log",q:"Complétez la série : A1 – C4 – E9 – G16 – ?",o:["I21","I25","J20","J24"],a:1,e:"Une lettre sur deux (A, C, E, G, I) et les carrés 1, 4, 9, 16, 25.",s:"QCM inspecteur 2026, Q34"},
{id:"i26-35",t:"log",q:"Une boîte contient 5 boules rouges, 7 bleues et 3 vertes. Quelle est la probabilité de tirer une boule verte ?",o:["14 %","20 %","25 %","30 %"],a:1,e:"3 / 15 = 1/5 = 20 %.",s:"QCM inspecteur 2026, Q35"},
{id:"i26-38",t:"log",q:"Complétez : CANARD – BIBELOT – CHACAL – DEMANDER – ÉCUREUIL – SIFFLET – GAGNER – ?",o:["FILLES","HACHOIR","INCENDIE","PÂQUES"],a:1,e:"Chaque mot contient deux fois la lettre suivante de l'alphabet : A, B, C, D, E, F, G, puis H (HACHOIR).",s:"QCM inspecteur 2026, Q38"},
{id:"i26-39",t:"log",q:"Si aujourd'hui est lundi, quel jour sera-t-on dans 45 jours ?",o:["Mercredi","Jeudi","Vendredi","Samedi"],a:1,e:"45 = 6 × 7 + 3 : lundi + 3 jours = jeudi.",s:"QCM inspecteur 2026, Q39"},
{id:"i26-40",t:"log",q:"Marie est la sœur de Jean. Jean est le frère de Paul. Paul est le fils de Louise. Louise est la mère de Marc. Quel est le lien de Marie avec Marc ?",o:["Sa cousine","Sa mère","Sa sœur","Sa tante"],a:2,e:"Louise est la mère de Paul et de Marc ; Marie, sœur de Paul, est donc la sœur de Marc.",s:"QCM inspecteur 2026, Q40"},
{id:"i26-41",t:"ang",q:"What's the English for: « Tu as soif ? Il y a de la limonade dans le cellier et du jus d'orange à la cave. Sers-toi. »",o:["Are you thirsty? There is some limonade in the cellar and some orange juice in the cave. Help yourself.","Are you thirsty? There is some limonade in the storeroom and some orange juicce in the cellar. Help yourself.","Are you thirsty? There is some limonade in the storeroom and some orrange juice in the cave. Help yourself.","Are you thirsty? There is some limonade in the storeroom and some orange juice in the cellar. Help yourself."],a:3,e:"Cellier = storeroom ; cave = cellar (cave = grotte). Les options 2 et 3 contiennent des fautes (juicce, orrange). Les 4 options gardent « limonade » (en anglais : lemonade).",s:"QCM inspecteur 2026, Q41"},
{id:"i26-42",t:"ang",q:"Complete: « I am starving. What are we having … lunch? »",o:["at","for","in","on"],a:1,e:"« for lunch / for dinner » : le repas.",s:"QCM inspecteur 2026, Q42"},
{id:"i26-43",t:"ang",q:"Find the synonym of « obvious » in: « The solution to this question is obvious. »",o:["Clear","Hard","Impossible","Weird"],a:0,e:"Obvious = évident = clear.",s:"QCM inspecteur 2026, Q43"},
{id:"i26-44",t:"ang",q:"Which sentence is correct?",o:["Paul drove when he stopped smoking","Paul drove when he stopped to smoke","Paul was driving when he stopped to smoke","Paul was driving when he stopped to smoking"],a:2,e:"Grille officielle : 3. Action en cours interrompue : past continuous (was driving) ; « stop to + verbe » = s'arrêter pour. Les phrases 1 et 2 sont grammaticales mais ne décrivent pas une action en cours ; la 4 est fautive.",s:"QCM inspecteur 2026, Q44"},
{id:"i26-45",t:"ang",q:"« One of the direct consequences of Brexit was the restoration of customs. » What does « customs » mean?",o:["Douanes","Frontières","Impôts","Passeports"],a:0,e:"Customs = douane(s). Frontière = border.",s:"QCM inspecteur 2026, Q45"},

// ---------- Sujet test inspecteur (épreuve 2, QCM) ----------
{id:"it-01",t:"admin",q:"Selon l'article 8 de la Constitution, les membres du Gouvernement sont nommés par :",o:["Le Président de l'Assemblée nationale","Le Président de la République sur proposition du Premier ministre","Le Président du Sénat","Le Secrétaire général du Gouvernement"],a:1,e:"Art. 8 : le Président nomme le Premier ministre, puis, sur sa proposition, les autres membres du Gouvernement.",x:"Le Président met fin aux fonctions du Premier ministre sur présentation par celui-ci de la démission du Gouvernement. Il n'y a pas de vote d'investiture obligatoire : le Gouvernement est responsable devant l'Assemblée nationale (art. 49 et 50).",u:["https://fr.wikipedia.org/wiki/Article_8_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise","https://www.vie-publique.fr/fiches/19454-quel-est-le-role-du-gouvernement"],s:"Sujet test inspecteur, Q1"},
{id:"it-02",t:"admin",q:"Parmi les 4 principes budgétaires ci-dessous, trouvez l'intrus.",o:["L'annualité","La spécialité","L'intégrité","L'universalité"],a:2,e:"Les principes budgétaires classiques sont l'annualité, l'unité, l'universalité et la spécialité. L'« intégrité » n'en fait pas partie.",x:"La LOLF y ajoute le principe de sincérité. Ne pas confondre l'universalité (toutes les recettes financent toutes les dépenses) et l'unité (un document unique retraçant toutes les recettes et dépenses).",u:["https://www.vie-publique.fr/fiches/21823-quels-sont-les-grands-principes-budgetaires"],s:"Sujet test inspecteur, Q2"},
{id:"it-03",t:"admin",q:"À quelle période a eu lieu l'acte I de la décentralisation ?",o:["Entre 1968 et 1972","Entre 1974 et 1978","Entre 1982 et 1986","Entre 1995 et 1999"],a:2,e:"Acte I : lois Defferre (loi du 2 mars 1982, lois de 1983) ; les premières élections régionales au suffrage universel direct ont lieu en 1986.",x:"La loi du 2 mars 1982 supprime la tutelle a priori du préfet et transfère l'exécutif départemental et régional aux présidents de conseil. L'acte II date de 2003-2004 (révision constitutionnelle du 28 mars 2003), l'acte III de 2014-2015 (lois MAPTAM et NOTRe).",u:["https://www.vie-publique.fr/fiches/19608-quest-ce-que-lacte-i-de-la-decentralisation-les-lois-defferre","https://www.vie-publique.fr/eclairage/38438-les-lois-defferre-premieres-lois-de-decentralisation"],s:"Sujet test inspecteur, Q3"},
{id:"it-04",t:"admin",q:"Que signifie l'acronyme « EPCI » ?",o:["Établissement public de collaboration internationale","Établissement public de concertation interne","Établissement public de coopération intercommunale","Établissement public de consultation intercommunale"],a:2,e:"EPCI = établissement public de coopération intercommunale (communautés de communes, d'agglomération, urbaines, métropoles).",x:"Les EPCI à fiscalité propre lèvent leurs propres impôts ; les syndicats de communes n'en ont pas. Depuis 2014, les conseillers communautaires sont élus en même temps que les conseillers municipaux (fléchage).",u:["https://www.vie-publique.fr/fiches/20118-la-cooperation-intercommunale-et-les-epci","https://www.vie-publique.fr/fiches/20115-comment-sont-creees-les-structures-intercommunales-epci"],s:"Sujet test inspecteur, Q4"},
{id:"it-05",t:"admin",q:"Qu'est-ce que la déconcentration ?",o:["Un transfert de missions entre collectivités territoriales","Un transfert de missions entre une agence nationale et une autorité indépendante","Un transfert de pouvoirs entre administrations","Un transfert de pouvoirs entre l'administration centrale et les représentants locaux"],a:3,e:"La déconcentration confie des pouvoirs de décision aux représentants locaux de l'État (préfets, services déconcentrés), qui restent soumis au pouvoir hiérarchique.",x:"À ne pas confondre avec la décentralisation, qui transfère des compétences à des collectivités territoriales dotées de la personnalité morale et d'organes élus. Formule d'Odilon Barrot : « c'est le même marteau qui frappe, mais on en a raccourci le manche ».",u:["https://www.vie-publique.fr/fiches/20167-quest-ce-que-la-deconcentration","https://www.vie-publique.fr/eclairage/38686-la-deconcentration-corollaire-de-la-decentralisation"],s:"Sujet test inspecteur, Q5"},
{id:"it-06",t:"admin",q:"Quelle est la date de création de l'ARCOM (Autorité de régulation de la communication audiovisuelle et numérique) ?",o:["Le 1er janvier 2021","Le 1er janvier 2022","Le 1er janvier 2023","Le 1er janvier 2024"],a:1,e:"L'ARCOM est née le 1er janvier 2022 de la fusion du CSA et de la Hadopi (loi du 25 octobre 2021).",x:"C'est une autorité publique indépendante. Elle régule l'audiovisuel, lutte contre le piratage et contrôle certaines obligations des plateformes en ligne ; elle est le coordinateur national pour le règlement européen sur les services numériques (DSA).",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_de_r%C3%A9gulation_de_la_communication_audiovisuelle_et_num%C3%A9rique"],s:"Sujet test inspecteur, Q6"},
{id:"it-07",t:"admin",q:"Qui élabore la loi de finances ?",o:["Le Conseil d'État","Les députés","Le Gouvernement","Les sénateurs"],a:2,e:"Le projet de loi de finances est préparé par le Gouvernement (ministre chargé du budget) puis voté par le Parlement.",x:"Le PLF est déposé en premier à l'Assemblée nationale, au plus tard le 1er mardi d'octobre. Le Parlement dispose de 70 jours pour se prononcer ; au-delà, le Gouvernement peut mettre le projet en vigueur par ordonnance (art. 47).",u:["https://www.vie-publique.fr/fiches/21870-quelles-sont-les-etapes-delaboration-dune-loi-de-finances","https://www.vie-publique.fr/fiches/21872-quelles-sont-les-etapes-dadoption-dune-loi-de-finances"],s:"Sujet test inspecteur, Q7"},
{id:"it-08",t:"admin",q:"Selon l'article 72 de la Constitution, le représentant de l'État dans les collectivités territoriales représente :",o:["Chacun des membres du Gouvernement","Le Ministre de l'Intérieur","Le Premier ministre","Le Président de la République"],a:0,e:"Art. 72, dernier alinéa : le représentant de l'État, représentant de chacun des membres du Gouvernement, a la charge des intérêts nationaux, du contrôle administratif et du respect des lois.",x:"Ce représentant est le préfet. Il est nommé par décret du Président de la République en Conseil des ministres et exerce le contrôle de légalité des actes des collectivités.",u:["https://www.vie-publique.fr/fiches/20169-quel-est-le-role-dun-prefet","https://fr.wikipedia.org/wiki/Pr%C3%A9fet_(France)"],s:"Sujet test inspecteur, Q8"},
{id:"it-09",t:"admin",q:"Quel texte consacre le principe de consentement à l'impôt ?",o:["La Constitution de la Ve République de 1958","La Convention européenne des droits de l'homme de 1953","La Déclaration des droits de l'homme et du citoyen de 1789","Le Préambule de la Constitution de 1946"],a:2,e:"Art. 14 de la DDHC : les citoyens ont le droit de constater, par eux-mêmes ou par leurs représentants, la nécessité de la contribution publique et de la consentir librement.",x:"L'art. 13 pose le principe d'égalité devant les charges publiques (contribution répartie selon les facultés). La DDHC fait partie du bloc de constitutionnalité.",u:["https://fr.wikipedia.org/wiki/Consentement_%C3%A0_l%27imp%C3%B4t","https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/declaration-des-droits-de-l-homme-et-du-citoyen-de-1789"],s:"Sujet test inspecteur, Q9"},
{id:"it-10",t:"admin",q:"Selon l'Insee, quelle part du PIB représente le déficit public de la France en 2023 ?",o:["3,1 %","4,2 %","5,5 %","7,5 %"],a:2,e:"Déficit public 2023 : 5,5 % du PIB (estimation publiée par l'Insee en mars 2024).",x:"Le déficit a atteint 5,8 % du PIB en 2024. Le seuil de référence européen est de 3 % ; la France fait l'objet d'une procédure pour déficit excessif depuis juillet 2024.",u:["https://fr.wikipedia.org/wiki/D%C3%A9ficit_public","https://fr.wikipedia.org/wiki/Proc%C3%A9dure_de_d%C3%A9ficit_public_excessif"],s:"Sujet test inspecteur, Q10",act:1},
{id:"it-11",t:"ue",q:"En quelle année l'Union européenne a-t-elle reçu le prix Nobel de la paix ?",o:["2001","2004","2007","2012"],a:3,e:"Prix Nobel de la paix 2012, pour sa contribution à la paix, à la réconciliation, à la démocratie et aux droits de l'homme en Europe.",x:"Le prix a été reçu à Oslo par les présidents du Conseil européen (Herman Van Rompuy), de la Commission (José Manuel Barroso) et du Parlement européen (Martin Schulz).",u:["https://fr.wikipedia.org/wiki/Prix_Nobel_de_la_paix_2012"],s:"Sujet test inspecteur, Q11"},
{id:"it-12",t:"ue",q:"De combien de commissaires est composée la Commission européenne ?",o:["24","25","26","27"],a:3,e:"27 commissaires, un par État membre, président et haut représentant compris.",x:"Le traité de Lisbonne prévoyait de réduire leur nombre aux deux tiers des États, mais le Conseil européen a maintenu la règle d'un commissaire par État. La Commission est nommée pour 5 ans après un vote d'approbation du Parlement européen.",u:["https://www.vie-publique.fr/fiches/20331-comment-sont-nommes-les-membres-de-la-commission-europeenne","https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"Sujet test inspecteur, Q12"},
{id:"it-13",t:"ue",q:"Quelle est la contribution de la France à l'Union européenne en 2024 ?",o:["21,6 milliards","22,5 milliards","23,1 milliards","23,9 milliards"],a:0,e:"Le prélèvement sur recettes au profit de l'UE était évalué à 21,6 milliards d'euros dans la loi de finances pour 2024.",x:"La France est le deuxième contributeur net au budget européen après l'Allemagne. Cette contribution prend la forme d'un prélèvement sur les recettes de l'État, et non d'une dépense budgétaire.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Sujet test inspecteur, Q13",act:1},
{id:"it-14",t:"ue",q:"Quel est le dernier traité adopté par l'Union européenne ?",o:["Traité d'Amsterdam","Traité de Lisbonne","Traité de Maastricht","Traité de Rome"],a:1,e:"Traité de Lisbonne, signé le 13 décembre 2007, entré en vigueur le 1er décembre 2009.",x:"Ordre chronologique : Rome (1957), Maastricht (1992), Amsterdam (1997), Nice (2001), Lisbonne (2007). Lisbonne a repris l'essentiel du projet de Constitution européenne rejeté en 2005.",u:["https://www.vie-publique.fr/fiches/20315-quest-ce-que-le-traite-de-lisbonne","https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"Sujet test inspecteur, Q14"},
{id:"it-15",t:"ue",q:"En quelle année a été mise en place la Politique agricole commune ?",o:["1951","1957","1962","1965"],a:2,e:"La PAC, prévue par le traité de Rome (1957), est mise en œuvre en 1962.",x:"Ses objectifs initiaux : accroître la productivité, assurer un niveau de vie équitable aux agriculteurs, stabiliser les marchés. Elle reste l'un des premiers postes du budget européen.",u:["https://www.vie-publique.fr/fiches/20381-quest-ce-que-la-politique-agricole-commune-pac","https://www.touteleurope.eu/histoire/histoire-de-la-politique-agricole-commune/"],s:"Sujet test inspecteur, Q15"},
{id:"it-16",t:"ue",q:"Quelle est la principale mission de la Banque centrale européenne ?",o:["Gérer les dossiers de surendettement des particuliers","Promouvoir la coopération monétaire internationale","Soutenir les pays en voie de développement","Veiller à la stabilité des prix"],a:3,e:"Le mandat principal de la BCE est la stabilité des prix dans la zone euro (objectif d'inflation de 2 % à moyen terme).",x:"La BCE, installée à Francfort, définit la politique monétaire de la zone euro et supervise les grandes banques depuis 2014. La promotion de la coopération monétaire internationale est la mission du FMI.",u:["https://www.vie-publique.fr/fiches/21800-quel-est-le-role-de-la-banque-centrale-europeenne-bce","https://fr.wikipedia.org/wiki/Banque_centrale_europ%C3%A9enne"],s:"Sujet test inspecteur, Q16"},
{id:"it-17",t:"ue",q:"En 2024, combien y a-t-il d'États membres dans l'Union européenne ?",o:["25","26","27","28"],a:2,e:"27 États membres depuis la sortie du Royaume-Uni le 31 janvier 2020.",x:"Le dernier État entré est la Croatie (2013). Plusieurs pays sont candidats (Ukraine, Moldavie, Balkans occidentaux, Turquie…).",s:"Sujet test inspecteur, Q17"},
{id:"it-18",t:"ue",q:"Comment sont élus les députés européens ?",o:["Au suffrage universel direct","Au suffrage universel indirect","Au scrutin mixte","Au scrutin proportionnel"],a:0,e:"Depuis 1979, les députés européens sont élus au suffrage universel direct pour 5 ans.",x:"En France, le scrutin est proportionnel sur une liste nationale unique (seuil de 5 %). La 4e proposition décrit donc le mode de scrutin français, mais la réponse attendue porte sur le mode d'élection.",u:["https://www.vie-publique.fr/fiches/20339-combien-y-t-il-de-deputes-au-parlement-europeen","https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"Sujet test inspecteur, Q18"},
{id:"it-19",t:"ue",q:"Parmi les ressources suivantes de l'Union européenne, trouvez l'intrus.",o:["Les amendes infligées aux entreprises qui enfreignent les règles de concurrence","La contribution des États membres fondée sur la taxe sur la valeur ajoutée","La contribution des États membres fondée sur le revenu brut national","Les droits de douane"],a:0,e:"Droits de douane, ressource TVA et ressource RNB sont des ressources propres. Les amendes de concurrence sont des « autres recettes ».",x:"Depuis 2021 s'y ajoute une ressource propre fondée sur les déchets d'emballages plastiques non recyclés. La ressource RNB est la plus importante.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Sujet test inspecteur, Q19"},
{id:"it-20",t:"ue",q:"En quelle année a été mise en place la Cour européenne des droits de l'homme ?",o:["1952","1959","1989","2004"],a:1,e:"La CEDH est instituée en 1959 à Strasbourg, en application de la Convention européenne des droits de l'homme (1950).",x:"Piège : la CEDH relève du Conseil de l'Europe (46 États), pas de l'Union européenne. Ne pas la confondre avec la Cour de justice de l'UE, installée à Luxembourg.",u:["https://www.vie-publique.fr/fiches/38293-quel-est-le-role-de-la-cour-europeenne-des-droits-de-lhomme","https://www.touteleurope.eu/institutions/quelle-est-la-difference-entre-la-cour-de-justice-de-l-union-europeenne-cjue-et-la-cour-europeenne-des-droits-de-l-homme-cedh/"],s:"Sujet test inspecteur, Q20"},
{id:"it-21",t:"num",q:"Qu'est-ce qu'Internet ?",o:["Un navigateur","Un réseau informatique mondial","Un système d'exploitation","Un dispositif de sécurité"],a:1,e:"Internet est le réseau mondial qui interconnecte des réseaux informatiques grâce aux protocoles TCP/IP.",x:"Le Web n'est qu'un des services d'Internet, comme la messagerie. Un navigateur (Firefox, Chrome, Edge) est le logiciel qui affiche les pages web.",u:["https://fr.wikipedia.org/wiki/Internet"],s:"Sujet test inspecteur, Q21"},
{id:"it-22",t:"num",q:"Lorsque l'on consulte un site, quelle est l'information transmise par le navigateur qui indiquera au serveur web où acheminer la page demandée ?",o:["L'adresse électronique","L'adresse IP","L'identifiant","L'URL"],a:3,e:"La grille officielle retient l'URL : c'est l'adresse de la page demandée. Attention, c'est l'adresse IP du poste qui permet techniquement de renvoyer la page à l'internaute.",x:"Une URL comprend le protocole (https), le nom de domaine et le chemin de la ressource. Le nom de domaine est traduit en adresse IP du serveur par le DNS.",u:["https://fr.wikipedia.org/wiki/Uniform_Resource_Locator","https://fr.wikipedia.org/wiki/Adresse_IP"],s:"Sujet test inspecteur, Q22"},
{id:"it-23",t:"num",q:"Qu'est-ce que le droit à l'oubli ?",o:["Le fait d'avoir trois essais pour saisir son mot de passe sans erreur","Le fait de pouvoir demander le renvoi d'un mot de passe si l'usager l'a oublié","Le fait de pouvoir paramétrer une déconnexion automatique de sa session personnelle","Le fait qu'un usager puisse faire retirer les contenus en ligne le concernant"],a:3,e:"Le droit à l'oubli permet de faire effacer ou déréférencer des données personnelles en ligne.",x:"Il a été consacré par la CJUE (arrêt Google Spain, 2014) puis par le RGPD (art. 17, droit à l'effacement). Il se demande au site ou au moteur de recherche, puis à la CNIL en cas de refus.",u:["https://www.cnil.fr/fr/le-dereferencement-dun-contenu-dans-un-moteur-de-recherche","https://fr.wikipedia.org/wiki/Droit_à_l'oubli"],s:"Sujet test inspecteur, Q23"},
{id:"it-24",t:"num",q:"Qu'est-ce que l'accessibilité numérique ?",o:["Le fait d'être dans une zone couverte par le Wi-Fi","Le fait que les contenus numériques soient consultables par tous, y compris par les personnes en situation de handicap","Le fait que les documents soient diffusés dans un format ouvert","Le fait que tous les contenus en ligne soient accessibles sans authentification"],a:1,e:"L'accessibilité numérique rend les services en ligne utilisables par tous, notamment les personnes en situation de handicap.",x:"Elle est obligatoire pour les services publics (loi du 11 février 2005). En France, le référentiel est le RGAA ; chaque site public doit afficher une déclaration d'accessibilité.",u:["https://accessibilite.numerique.gouv.fr/","https://fr.wikipedia.org/wiki/Référentiel_général_d'amélioration_de_l'accessibilité"],s:"Sujet test inspecteur, Q24"},
{id:"it-25",t:"num",q:"Quel raccourci clavier est utilisé pour sélectionner tout le texte d'un document ?",o:["CTRL + A","CTRL + F","CTRL + N","CTRL + T"],a:0,e:"Ctrl + A sélectionne tout (« All »).",x:"Ctrl + F lance une recherche, Ctrl + N ouvre un nouveau document ou une nouvelle fenêtre, Ctrl + T ouvre un nouvel onglet dans un navigateur.",s:"Sujet test inspecteur, Q25"},
{id:"it-26",t:"num",q:"Qu'est-ce qu'un VPN ?",o:["Un logiciel de messagerie","Un outil de création de sites internet","Un outil garantissant une navigation internet sécurisée","Un outil permettant l'organisation de visioconférences"],a:2,e:"Un VPN (réseau privé virtuel) crée un tunnel chiffré entre l'appareil et un serveur distant.",x:"Il sert notamment au télétravail pour accéder au réseau interne de l'administration, et masque l'adresse IP de l'utilisateur. Il ne protège ni contre l'hameçonnage ni contre les logiciels malveillants.",u:["https://fr.wikipedia.org/wiki/R%C3%A9seau_priv%C3%A9_virtuel"],s:"Sujet test inspecteur, Q26"},
{id:"it-27",t:"num",q:"Quelle est la principale mission de la CNIL ?",o:["L'accompagnement des professionnels dans la création de leur site internet","La lutte contre les sites frauduleux","La protection des données personnelles","Le recouvrement des taxes sur les GAFAM"],a:2,e:"La CNIL, autorité administrative indépendante créée en 1978, protège les données personnelles.",x:"Elle informe, conseille, contrôle et peut sanctionner (amende jusqu'à 20 M€ ou 4 % du chiffre d'affaires mondial au titre du RGPD).",u:["https://fr.wikipedia.org/wiki/Commission_nationale_de_l%27informatique_et_des_libert%C3%A9s","https://www.cnil.fr/fr/le-cadre-national/la-loi-informatique-et-libertes"],s:"Sujet test inspecteur, Q27"},
{id:"it-28",t:"num",q:"Quel est le raccourci clavier permettant de rechercher un mot dans un document ?",o:["CTRL + A","CTRL + C","CTRL + F","CTRL + V"],a:2,e:"Ctrl + F (« Find ») ouvre la recherche.",x:"Ctrl + C copie, Ctrl + V colle, Ctrl + X coupe, Ctrl + Z annule. Ctrl + H ouvre « Rechercher et remplacer » dans la plupart des traitements de texte.",s:"Sujet test inspecteur, Q28"},
{id:"it-29",t:"num",q:"Qu'est-ce que la mémoire vive d'un ordinateur ?",o:["Une mémoire à accès aléatoire","Une mémoire délocalisée","Une mémoire de stockage","Une mémoire virtuelle"],a:0,e:"Mémoire vive = RAM (Random Access Memory), mémoire à accès aléatoire.",x:"Elle est volatile : son contenu s'efface à l'extinction. Le stockage durable relève du disque dur ou du SSD ; la ROM (mémoire morte) n'est accessible qu'en lecture.",u:["https://fr.wikipedia.org/wiki/M%C3%A9moire_vive"],s:"Sujet test inspecteur, Q29"},
{id:"it-30",t:"num",q:"Si une information de profil est en « accès public », qu'est-ce que cela signifie ?",o:["Cette information est adaptée aux jeunes de moins de 12 ans","Cette information n'est pas soumise au droit d'auteur","Cette information peut être modifiée par tout internaute","Cette information peut être vue par tout internaute"],a:3,e:"« Public » signifie visible par tous, y compris des personnes extérieures à son réseau.",x:"Une information publique peut être copiée, indexée par les moteurs de recherche et réutilisée. Pour un agent public, les paramètres de confidentialité sont aussi une question de devoir de réserve.",s:"Sujet test inspecteur, Q30"},
{id:"it-31",t:"log",q:"Quel nombre complète logiquement ce tableau ? Ligne 1 : 1 – 1 – 1 – 1 ; ligne 2 : 1 – 3 – 5 – 7 ; ligne 3 : 1 – 5 – 13 – 25 ; ligne 4 : 1 – 7 – 25 – ?",o:["33","50","63","97"],a:2,e:"Chaque case = case de gauche + case du dessus + case en diagonale haut-gauche. Ex. : 13 = 5 + 5 + 3. Donc ? = 25 + 25 + 13 = 63.",s:"Sujet test inspecteur, Q31"},
{id:"it-32",t:"log",q:"Pluie est à Neige, ce que :",o:["Bois est à Feu","Fusion est à Métal","Glace est à Eau","Vapeur est à Eau"],a:3,e:"De la pluie à la neige, l'eau passe à l'état plus froid (liquide → solide). De la vapeur à l'eau aussi (gaz → liquide). Glace → Eau va dans l'autre sens.",s:"Sujet test inspecteur, Q32"},
{id:"it-33",t:"log",q:"Trois triangles portent un nombre à chaque coin (gauche, droite, bas) et un nombre au centre : (4, 6, 6) → 32 ; (11, 9, 6) → 43 ; (3, 10, 4) → ?. Quel est le nombre manquant ?",o:["23","31","37","54"],a:2,e:"Centre = droite × bas − gauche : 6 × 6 − 4 = 32 ; 9 × 6 − 11 = 43 ; 10 × 4 − 3 = 37.",s:"Sujet test inspecteur, Q33 (énoncé en image, retranscrit)"},
{id:"it-34",t:"log",q:"Si Nizard va à Dublin, si Shyrel va à Londres, où va Ethel ?",o:["Berlin","Dublin","Lisbonne","Rome"],a:2,e:"La dernière lettre du prénom donne la première lettre de la ville : NizarD → Dublin, ShyreL → Londres, EtheL → Lisbonne.",s:"Sujet test inspecteur, Q34"},
{id:"it-35",t:"log",q:"Complétez la série : 12 – E – 19 – L – 23 – P – 18 – ?",o:["I","K","Q","V"],a:1,e:"Chaque lettre a pour rang le nombre qui la précède moins 7 : 12 − 7 = 5 (E), 19 − 7 = 12 (L), 23 − 7 = 16 (P), 18 − 7 = 11 (K).",s:"Sujet test inspecteur, Q35"},
{id:"it-36",t:"log",q:"Trouvez l'intrus.",o:["6324","7431","7432","13723"],a:2,e:"DOUTEUSE. La grille officielle donne 7432, mais aucune règle simple ne l'isole : sommes des chiffres 15, 15, 16, 16 ; divisibles par 3 : 6324 et 7431 seulement. Question exclue des examens et du score.",s:"Sujet test inspecteur, Q36",d:1},
{id:"it-37",t:"log",q:"Il y a trois ans, Mathieu avait cinq fois l'âge d'Olivia ; aujourd'hui, Mathieu a trois fois l'âge d'Olivia. Quel âge a Olivia ?",o:["5","6","10","15"],a:1,e:"M = 3O et M − 3 = 5(O − 3), donc 3O − 3 = 5O − 15, soit O = 6 (Mathieu a 18 ans ; il y a 3 ans : 15 = 5 × 3).",s:"Sujet test inspecteur, Q37"},
{id:"it-38",t:"log",q:"Parmi ces mots dont les lettres sont à remettre dans l'ordre, quel est l'intrus ?",o:["GANOER","SIRECE","TRICOBA","TVAACO"],a:0,e:"GANOER = ORANGE, SIRECE = CERISE, TRICOBA = ABRICOT, TVAACO = AVOCAT. Cerise, abricot et avocat sont des fruits à noyau ; l'orange a des pépins.",s:"Sujet test inspecteur, Q38"},
{id:"it-39",t:"log",q:"Deux rangées de cartes. En haut : as de pique, 3 de cœur, 5 de carreau, 8 de trèfle. En bas : 6 de pique, 5 de cœur, ?, 2 de trèfle. Quelle est la carte manquante ?",o:["4 de carreau","4 de cœur","3 de trèfle","3 de carreau"],a:0,e:"Chaque colonne garde la même couleur et la somme des deux cartes augmente de 1 : 1 + 6 = 7, 3 + 5 = 8, 5 + ? = 9, 8 + 2 = 10. Donc 4 de carreau.",s:"Sujet test inspecteur, Q39 (énoncé en image, retranscrit)"},
{id:"it-40",t:"log",q:"Quel jour est avant-hier, si lundi est 3 jours avant après-demain ?",o:["Dimanche","Jeudi","Mardi","Samedi"],a:0,e:"Après-demain = lundi + 3 = jeudi, donc aujourd'hui = mardi et avant-hier = dimanche.",s:"Sujet test inspecteur, Q40"},
{id:"it-41",t:"ang",q:"Complete the following sentence: « She said that she had already watched the film … television. »",o:["at","in","from","on"],a:3,e:"On television, on TV, on the radio : préposition « on ».",s:"Sujet test inspecteur, Q41"},
{id:"it-42",t:"ang",q:"Find the odd one in the following list:",o:["Cheetah","Ostrich","Owl","Sparrow"],a:0,e:"Cheetah = guépard (mammifère). Ostrich (autruche), owl (hibou, chouette) et sparrow (moineau) sont des oiseaux.",s:"Sujet test inspecteur, Q42"},
{id:"it-43",t:"ang",q:"Complete the sentence with the right word: « If I … you, I would refund Jim. »",o:["been","have","was","were"],a:3,e:"Conditionnel de 2e type : « If I were you » (were à toutes les personnes dans la langue soignée).",s:"Sujet test inspecteur, Q43"},
{id:"it-44",t:"ang",q:"My uncle's wife is my …",o:["aunt","cousin","mother","niece"],a:0,e:"La femme de mon oncle est ma tante : aunt. Niece = nièce, cousin = cousin(e).",s:"Sujet test inspecteur, Q44"},
{id:"it-45",t:"ang",q:"Complete the following sentence: « The recent … caused widespread devastation. »",o:["huricane","huricanne","hurricane","hurricanne"],a:2,e:"Orthographe : hurricane (ouragan), deux r et un n.",s:"Sujet test inspecteur, Q45"},

// ---------- QCM d'entraînement inédit (fichier 02) ----------
{id:"e-01",t:"admin",q:"Quel article de la Constitution fixe le domaine de la loi ?",o:["Article 20","Article 37","Article 49","Article 34"],a:3,e:"Art. 34 : domaine de la loi ; art. 37 : tout le reste relève du règlement.",x:"La loi « fixe les règles » dans certaines matières et « détermine les principes fondamentaux » dans d'autres. Le Gouvernement peut faire constater par le Conseil constitutionnel le caractère réglementaire d'un texte de forme législative (art. 37 al. 2).",u:["https://www.vie-publique.fr/fiches/19479-pouvoir-legislatif-et-pouvoir-reglementaire-sous-la-ve-republique","https://fr.wikipedia.org/wiki/Article_34_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Entraînement, Q1"},
{id:"e-02",t:"admin",q:"Combien de membres nommés compte le Conseil constitutionnel ?",o:["7","9","12","15"],a:1,e:"9 membres pour 9 ans, renouvelés par tiers tous les 3 ans (plus les anciens présidents, membres de droit).",x:"Le président de la République, le président de l'Assemblée nationale et le président du Sénat en nomment chacun trois ; depuis 2008, ces nominations sont soumises à l'avis des commissions parlementaires. Le président du Conseil est nommé par le président de la République.",u:["https://www.vie-publique.fr/fiches/19554-quelle-est-la-composition-du-conseil-constitutionnel","https://www.conseil-constitutionnel.fr/le-conseil-constitutionnel/les-membres"],s:"Entraînement, Q2"},
{id:"e-03",t:"admin",q:"Depuis quelle année un justiciable peut-il soulever une question prioritaire de constitutionnalité (QPC) ?",o:["1958","1974","2002","2010"],a:3,e:"Créée par la révision du 23 juillet 2008, la QPC s'applique depuis le 1er mars 2010 (art. 61-1).",x:"La disposition déclarée inconstitutionnelle est abrogée à compter de la publication de la décision ou d'une date ultérieure fixée par le Conseil (art. 62). Le Conseil d'État ou la Cour de cassation ont 3 mois pour transmettre, et le Conseil constitutionnel 3 mois pour statuer.",u:["https://www.vie-publique.fr/questions-reponses/23811-la-question-prioritaire-de-constitutionnalite-qpc","https://fr.wikipedia.org/wiki/Question_prioritaire_de_constitutionnalit%C3%A9"],s:"Entraînement, Q3"},
{id:"e-04",t:"admin",q:"Dans la LOLF, quelle est l'unité de spécialité des crédits ?",o:["Le programme","La mission","L'action","Le titre"],a:0,e:"Les crédits sont votés par mission et spécialisés par programme.",x:"Chaque programme est confié à un responsable de programme et assorti d'objectifs et d'indicateurs de performance (projet annuel de performances, puis rapport annuel de performances).",u:["https://www.vie-publique.fr/fiches/21875-comment-les-depenses-sont-elles-presentees-dans-le-budget-de-letat","https://fr.wikipedia.org/wiki/Loi_organique_relative_aux_lois_de_finances"],s:"Entraînement, Q4"},
{id:"e-05",t:"admin",q:"Quel principe budgétaire interdit d'affecter une recette à une dépense déterminée ?",o:["L'annualité","L'unité","L'universalité","La spécialité"],a:2,e:"Universalité : non-affectation et non-compensation.",x:"L'universalité comporte deux règles : la non-compensation (recettes et dépenses inscrites pour leur montant brut) et la non-affectation. Les comptes d'affectation spéciale et les fonds de concours y font exception.",u:["https://www.vie-publique.fr/fiches/21823-quels-sont-les-grands-principes-budgetaires","https://fr.wikipedia.org/wiki/Principe_d'universalit%C3%A9_budg%C3%A9taire"],s:"Entraînement, Q5"},
{id:"e-06",t:"admin",q:"De combien de jours le Parlement dispose-t-il pour se prononcer sur un projet de loi de finances ?",o:["40 jours","50 jours","70 jours","90 jours"],a:2,e:"Art. 47 : 70 jours, sinon mise en œuvre par ordonnance. 50 jours pour la loi de financement de la Sécurité sociale.",x:"Le PLF est d'abord examiné par l'Assemblée nationale (40 jours en première lecture), puis par le Sénat. Le délai de 70 jours court à compter du dépôt du projet.",u:["https://www.vie-publique.fr/fiches/300659-dans-quel-cas-le-budget-peut-il-etre-adopte-par-ordonnance-article-473","https://www.vie-publique.fr/fiches/21872-quelles-sont-les-etapes-dadoption-dune-loi-de-finances"],s:"Entraînement, Q6"},
{id:"e-07",t:"admin",q:"Qui exerce le contrôle de légalité sur les actes des collectivités territoriales ?",o:["La chambre régionale des comptes","Le Conseil d'État","Le directeur départemental des finances publiques","Le préfet"],a:3,e:"Le préfet peut déférer l'acte au tribunal administratif dans les 2 mois.",x:"Depuis 1982, le contrôle s'exerce a posteriori : la tutelle a priori a été supprimée. Les actes les plus importants doivent être transmis au préfet pour devenir exécutoires.",u:["https://www.collectivites-locales.gouv.fr/connaitre-les-acteurs-et-les-institutions/controle-de-legalite","https://www.vie-publique.fr/fiches/20195-comment-sexerce-le-controle-sur-les-actes-des-collectivites-locales"],s:"Entraînement, Q7"},
{id:"e-08",t:"admin",q:"Qu'a fait la loi NOTRe du 7 août 2015 ?",o:["Elle a supprimé la clause générale de compétence des départements et des régions","Elle a créé les métropoles","Elle a supprimé les départements","Elle a instauré l'élection des conseillers régionaux au suffrage direct"],a:0,e:"Les métropoles ont été créées par la loi RCT (2010) puis généralisées par la loi MAPTAM (2014).",x:"NOTRe signifie « nouvelle organisation territoriale de la République ». La loi a aussi relevé à 15 000 habitants le seuil minimal des intercommunalités (avec des dérogations) et transféré aux régions les transports interurbains et scolaires des départements.",u:["https://www.vie-publique.fr/fiches/20112-la-repartition-des-competences-entre-collectivites-apres-la-loi-notre","https://fr.wikipedia.org/wiki/Loi_portant_nouvelle_organisation_territoriale_de_la_R%C3%A9publique"],s:"Entraînement, Q8"},
{id:"e-09",t:"admin",q:"Un fonctionnaire reçoit un ordre manifestement illégal et de nature à compromettre gravement un intérêt public. Que doit-il faire ?",o:["L'exécuter, par obéissance hiérarchique","Refuser de l'exécuter","Demander l'avis du préfet","Saisir le Conseil constitutionnel"],a:1,e:"Seule exception légale au devoir d'obéissance hiérarchique.",x:"Les deux conditions sont cumulatives (art. L. 121-10 du Code général de la fonction publique). La règle vient de la jurisprudence Langneur du Conseil d'État (1944).",u:["https://www.vie-publique.fr/fiches/20259-quels-sont-les-devoirs-des-fonctionnaires","https://fr.wikipedia.org/wiki/Devoir_d'ob%C3%A9issance"],s:"Entraînement, Q9"},
{id:"e-10",t:"admin",q:"Fin juin 2026, la dette publique de la France représentait environ :",o:["60 % du PIB","98 % du PIB","119 % du PIB","140 % du PIB"],a:2,e:"3 595,5 Md€, soit 119,0 % du PIB (Insee, 29 septembre 2026).",x:"Le critère de Maastricht fixe un plafond de 60 % du PIB. La dette est un stock, alimenté chaque année par le déficit (un flux).",u:["https://www.vie-publique.fr/questions-reponses/304693-dette-publique-de-la-france-lessentiel-en-6-questions","https://fr.wikipedia.org/wiki/Dette_publique_de_la_France"],s:"Entraînement, Q10",act:1},
{id:"e-11",t:"ue",q:"En quelle année le traité de Maastricht a-t-il été signé ?",o:["1957","1986","1992","2007"],a:2,e:"Signé le 7 février 1992, en vigueur le 1er novembre 1993.",x:"En France, il a été approuvé de justesse par le référendum du 20 septembre 1992 (51 % de « oui »). Il crée l'Union européenne, fondée alors sur trois piliers.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Maastricht","https://www.vie-publique.fr/fiches/21798-quels-sont-les-criteres-de-maastricht-pour-participer-luem"],s:"Entraînement, Q11"},
{id:"e-12",t:"ue",q:"Combien d'États membres compte la zone euro au 1er janvier 2026 ?",o:["19","20","21","27"],a:2,e:"21 avec l'entrée de la Bulgarie (la Croatie était entrée en 2023).",x:"Les entrées depuis 2007 : Slovénie (2007), Chypre et Malte (2008), Slovaquie (2009), Estonie (2011), Lettonie (2014), Lituanie (2015), Croatie (2023), Bulgarie (2026).",u:["https://european-union.europa.eu/institutions-law-budget/euro/countries-using-euro_fr","https://fr.wikipedia.org/wiki/Zone_euro"],s:"Entraînement, Q12",act:1},
{id:"e-13",t:"ue",q:"Quelle institution dispose en principe de l'initiative législative dans l'UE ?",o:["La Commission européenne","Le Parlement européen","Le Conseil européen","Le Conseil de l'Union européenne"],a:0,e:"Monopole de l'initiative : la Commission propose, le Parlement et le Conseil adoptent.",x:"Le Parlement européen (art. 225 TFUE), le Conseil (art. 241 TFUE) et une initiative citoyenne d'un million de personnes peuvent seulement demander à la Commission de présenter une proposition.",u:["https://www.vie-publique.fr/fiches/20332-quel-est-le-role-de-la-commission-europeenne","https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"Entraînement, Q13"},
{id:"e-14",t:"ue",q:"Qu'est-ce qu'une directive européenne ?",o:["Un acte directement applicable sans transposition","Un acte sans force obligatoire","Un acte qui ne s'applique qu'aux États qui l'ont voté","Un acte qui lie les États quant au résultat à atteindre et qui doit être transposé"],a:3,e:"Art. 288 TFUE : la directive lie quant au résultat, en laissant le choix des moyens.",x:"Une directive non transposée dans le délai peut être invoquée par un particulier contre l'État si elle est claire, précise et inconditionnelle (effet direct vertical). Le Conseil d'État l'a admis dans l'arrêt Perreux (2009).",u:["https://www.vie-publique.fr/fiches/20371-actes-juridiques-de-lue-quest-ce-quune-directive","https://fr.wikipedia.org/wiki/Directive_de_l'Union_europ%C3%A9enne"],s:"Entraînement, Q14"},
{id:"e-15",t:"ue",q:"Où siège la Cour de justice de l'Union européenne ?",o:["Bruxelles","Strasbourg","Luxembourg","La Haye"],a:2,e:"Luxembourg. La Cour européenne des droits de l'homme siège à Strasbourg.",x:"La CJUE comprend la Cour de justice (un juge par État) et le Tribunal (deux juges par État). Elle juge notamment les recours en manquement et les renvois préjudiciels.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/court-justice-european-union-cjeu_fr","https://fr.wikipedia.org/wiki/Cour_de_justice_de_l'Union_europ%C3%A9enne"],s:"Entraînement, Q15"},
{id:"e-16",t:"ue",q:"Comment se définit la majorité qualifiée au Conseil de l'UE ?",o:["55 % des États représentant au moins 65 % de la population","50 % des États membres","Les deux tiers des États membres","L'unanimité moins une voix"],a:0,e:"Double majorité, en vigueur depuis le 1er novembre 2014 (traité de Lisbonne).",x:"Avec 27 États, il faut au moins 15 États (55 %) représentant 65 % de la population. Une minorité de blocage doit réunir au moins 4 États.",u:["https://www.vie-publique.fr/fiches/20348-le-vote-la-majorite-qualifiee-au-sein-du-conseil-de-lue"],s:"Entraînement, Q16"},
{id:"e-17",t:"ue",q:"Quelle est la principale ressource du budget de l'UE ?",o:["Les droits de douane","La ressource fondée sur la TVA","La ressource fondée sur le revenu national brut","La contribution sur les plastiques non recyclés"],a:2,e:"La ressource RNB représente de loin la plus grande part.",x:"Les autres ressources propres sont les droits de douane, la ressource TVA et, depuis 2021, la contribution sur les emballages plastiques non recyclés (0,80 € par kg).",u:["https://www.vie-publique.fr/fiches/20375-quelles-sont-les-ressources-de-lunion-europeenne","https://fr.wikipedia.org/wiki/Budget_de_l'Union_europ%C3%A9enne"],s:"Entraînement, Q17"},
{id:"e-18",t:"ue",q:"Lequel de ces organes n'est pas une institution de l'Union européenne ?",o:["La Cour européenne des droits de l'homme","La Cour des comptes européenne","La Banque centrale européenne","Le Conseil européen"],a:0,e:"La CEDH relève du Conseil de l'Europe (46 États).",x:"La CEDH, installée à Strasbourg, applique la Convention européenne des droits de l'homme de 1950. Les sept institutions de l'Union sont énumérées à l'article 13 du TUE.",u:["https://www.vie-publique.fr/fiches/20299-quest-ce-que-le-conseil-de-leurope","https://fr.wikipedia.org/wiki/Cour_europ%C3%A9enne_des_droits_de_l'homme"],s:"Entraînement, Q18"},
{id:"e-19",t:"ue",q:"Depuis quand la Charte des droits fondamentaux de l'UE a-t-elle une valeur juridique contraignante ?",o:["2000","2004","2009","2013"],a:2,e:"Proclamée à Nice en 2000, elle a la même valeur que les traités depuis l'entrée en vigueur de Lisbonne, le 1er décembre 2009.",x:"Ses 54 articles sont regroupés autour de six valeurs : dignité, libertés, égalité, solidarité, citoyenneté et justice. Elle s'impose aux institutions de l'Union et aux États lorsqu'ils mettent en œuvre le droit de l'Union.",u:["https://www.vie-publique.fr/fiches/20322-quest-ce-que-la-charte-des-droits-fondamentaux-de-lunion-europeenne","https://fr.wikipedia.org/wiki/Charte_des_droits_fondamentaux_de_l'Union_europ%C3%A9enne"],s:"Entraînement, Q19"},
{id:"e-20",t:"ue",q:"Quel est le dernier pays à avoir adhéré à l'Union européenne ?",o:["La Bulgarie","La Croatie","La Roumanie","La Slovénie"],a:1,e:"Croatie, 1er juillet 2013.",x:"La Croatie est entrée dans l'UE le 1er juillet 2013, puis dans la zone euro et l'espace Schengen le 1er janvier 2023.",u:["https://www.vie-publique.fr/fiches/20364-quest-ce-que-lelargissement-de-lunion-europeenne","https://fr.wikipedia.org/wiki/%C3%89largissement_de_l'Union_europ%C3%A9enne"],s:"Entraînement, Q20"},
{id:"e-21",t:"num",q:"Dans quel délai une violation de données personnelles doit-elle être notifiée à la CNIL ?",o:["24 heures","72 heures","7 jours","1 mois"],a:1,e:"RGPD, art. 33 : 72 heures au plus tard après en avoir pris connaissance.",x:"Si la violation présente un risque élevé pour les droits des personnes, celles-ci doivent aussi être informées dans les meilleurs délais (art. 34). Toute violation est consignée dans un registre interne, même non notifiée.",u:["https://www.cnil.fr/fr/services-en-ligne/notifier-une-violation-de-donnees-personnelles","https://fr.wikipedia.org/wiki/R%C3%A8glement_g%C3%A9n%C3%A9ral_sur_la_protection_des_donn%C3%A9es"],s:"Entraînement, Q21"},
{id:"e-22",t:"num",q:"Quel droit permet de récupérer ses données dans un format réutilisable pour les transmettre à un autre service ?",o:["Le droit d'accès","Le droit d'opposition","Le droit de rectification","Le droit à la portabilité"],a:3,e:"Droit à la portabilité (art. 20 RGPD).",x:"Il ne vise que les données fournies par la personne et traitées de façon automatisée sur la base du consentement ou d'un contrat. Ce droit est apparu avec le RGPD en 2018.",u:["https://www.cnil.fr/fr/comprendre-mes-droits/le-droit-la-portabilite-obtenir-et-reutiliser-une-copie-de-vos-donnees"],s:"Entraînement, Q22"},
{id:"e-23",t:"num",q:"Que signifie le principe de minimisation des données ?",o:["Ne collecter que les données nécessaires à la finalité du traitement","Chiffrer toutes les données","Supprimer les données au bout d'un an","Anonymiser toutes les données collectées"],a:0,e:"Données adéquates, pertinentes et limitées à ce qui est nécessaire.",x:"Principe posé à l'article 5 du RGPD, avec la licéité, la limitation des finalités, l'exactitude, la limitation de la conservation et la sécurité. Exemple : une inscription à une lettre d'information n'a pas à demander la date de naissance.",u:["https://www.cnil.fr/fr/minimiser-les-donnees-collectees","https://www.cnil.fr/fr/comprendre-le-rgpd/les-six-grands-principes-du-rgpd"],s:"Entraînement, Q23"},
{id:"e-24",t:"num",q:"Qu'est-ce qu'un rançongiciel ?",o:["Un logiciel publicitaire gratuit","Un logiciel de paiement en ligne","Un logiciel de sauvegarde automatique","Un logiciel qui chiffre les données d'une victime et exige une rançon"],a:3,e:"Ransomware.",x:"Les autorités recommandent de ne pas payer : le paiement ne garantit pas la récupération des données et finance les attaquants. La meilleure protection reste des sauvegardes régulières, dont une déconnectée du réseau.",u:["https://www.cnil.fr/fr/cybersecurite/multiplication-des-attaques-par-rancongiciel-comment-limiter-les-risques","https://fr.wikipedia.org/wiki/Ran%C3%A7ongiciel"],s:"Entraînement, Q24"},
{id:"e-25",t:"num",q:"Que signifie le « S » de HTTPS ?",o:["Simple","Secure","Server","Speed"],a:1,e:"Secure : les échanges sont chiffrés.",x:"HTTPS chiffre les échanges entre le navigateur et le serveur grâce au protocole TLS. Le cadenas ne garantit pas que le site soit honnête.",u:["https://fr.wikipedia.org/wiki/Hypertext_Transfer_Protocol_Secure"],s:"Entraînement, Q25"},
{id:"e-26",t:"num",q:"Qu'est-ce que FranceConnect ?",o:["Un dispositif qui permet d'accéder à de nombreux services publics en ligne avec un compte déjà existant","Un réseau wifi public gratuit","La messagerie sécurisée des agents de l'État","Le moteur de recherche de l'administration"],a:0,e:"Identification unique (via impots.gouv, ameli, La Poste…).",x:"Lancé en 2016, il évite de créer un identifiant pour chaque service. FranceConnect+ offre un niveau de sécurité renforcé pour les démarches sensibles.",u:["https://fr.wikipedia.org/wiki/FranceConnect"],s:"Entraînement, Q26"},
{id:"e-27",t:"num",q:"Que désigne l'informatique en nuage (cloud) ?",o:["L'utilisation de ressources informatiques à distance via Internet","Un réseau sans fil à longue portée","La prévision météorologique par ordinateur","Le stockage exclusif sur clé USB"],a:0,e:"SaaS, PaaS, IaaS : logiciel, plateforme ou infrastructure « en tant que service ».",x:"L'État a adopté en 2021 une doctrine « cloud au centre » ; pour les données sensibles, il exige des offres qualifiées SecNumCloud par l'ANSSI.",u:["https://fr.wikipedia.org/wiki/Cloud_computing","https://www.cnil.fr/fr/securite-cloud-informatique-en-nuage"],s:"Entraînement, Q27"},
{id:"e-28",t:"num",q:"Quelle autorité est chargée de la sécurité des systèmes d'information de l'État ?",o:["La CNIL","L'ANSSI","L'ARCOM","L'ARCEP"],a:1,e:"ANSSI (2009), rattachée au SGDSN. La CNIL protège les données personnelles.",x:"Créée en 2009, l'ANSSI est l'autorité nationale de cybersécurité ; elle qualifie notamment les produits et prestataires de sécurité. Pour les particuliers et les PME, le relais est cybermalveillance.gouv.fr.",u:["https://fr.wikipedia.org/wiki/Agence_nationale_de_la_s%C3%A9curit%C3%A9_des_syst%C3%A8mes_d'information"],s:"Entraînement, Q28"},
{id:"e-29",t:"num",q:"Selon quel critère le règlement européen sur l'IA (AI Act) classe-t-il les systèmes d'IA ?",o:["Leur prix","Leur niveau de risque","Leur pays d'origine","Leur nombre d'utilisateurs"],a:1,e:"Risque inacceptable (interdit), élevé, limité, minimal.",x:"Le règlement (UE) 2024/1689 est entré en vigueur le 1er août 2024, avec une application progressive : les pratiques interdites, comme la notation sociale, le sont depuis le 2 février 2025.",u:["https://www.vie-publique.fr/questions-reponses/292157-ai-act-le-reglement-europeen-sur-lintelligence-artificielle-ia","https://www.cnil.fr/fr/entree-en-vigueur-du-reglement-europeen-sur-lia-les-premieres-questions-reponses-de-la-cnil"],s:"Entraînement, Q29"},
{id:"e-30",t:"num",q:"Qu'est-ce qu'un logiciel libre ?",o:["Un logiciel forcément gratuit","Un logiciel sans aucune licence","Un logiciel réservé aux administrations","Un logiciel dont le code source peut être consulté, modifié et redistribué selon sa licence"],a:3,e:"Libre ne veut pas dire gratuit : c'est une question de libertés accordées par la licence.",x:"Les quatre libertés : exécuter, étudier, modifier et redistribuer le logiciel. Exemples : Linux, LibreOffice, Firefox.",u:["https://fr.wikipedia.org/wiki/Logiciel_libre"],s:"Entraînement, Q30"},
{id:"e-31",t:"log",q:"Quel nombre suit : 3 – 6 – 12 – 24 – ?",o:["36","42","48","50"],a:2,e:"Chaque terme double.",s:"Entraînement, Q31"},
{id:"e-32",t:"log",q:"Quel nombre suit : 2 – 3 – 5 – 8 – 12 – 17 – ?",o:["21","22","23","24"],a:2,e:"Écarts 1, 2, 3, 4, 5, puis 6 : 17 + 6 = 23.",s:"Entraînement, Q32"},
{id:"e-33",t:"log",q:"Complétez la série : B2 – D4 – F6 – H8 – ?",o:["I9","J10","K10","J12"],a:1,e:"Une lettre sur deux, nombre = rang de la lettre : J = 10.",s:"Entraînement, Q33"},
{id:"e-34",t:"log",q:"Si nous sommes mercredi, quel jour serons-nous dans 100 jours ?",o:["Jeudi","Vendredi","Samedi","Dimanche"],a:1,e:"100 = 14 × 7 + 2 : mercredi + 2 = vendredi.",s:"Entraînement, Q34"},
{id:"e-35",t:"log",q:"Un prix augmente de 20 %, puis baisse de 20 %. Quelle est sa variation globale ?",o:["0 %","−2 %","−4 %","+4 %"],a:2,e:"1,2 × 0,8 = 0,96, soit −4 %.",s:"Entraînement, Q35"},
{id:"e-36",t:"log",q:"Si CHAT s'écrit 3-8-1-20, comment s'écrit LOUP ?",o:["12-15-21-16","11-15-21-16","12-14-21-16","12-15-20-16"],a:0,e:"Rang dans l'alphabet : L = 12, O = 15, U = 21, P = 16.",s:"Entraînement, Q36"},
{id:"e-37",t:"log",q:"On lance deux dés équilibrés. Quelle est la probabilité que la somme fasse 7 ?",o:["1/12","1/9","1/6","1/3"],a:2,e:"6 cas favorables sur 36 : (1,6), (2,5), (3,4), (4,3), (5,2), (6,1).",s:"Entraînement, Q37"},
{id:"e-38",t:"log",q:"Trouvez l'intrus.",o:["Euro","Livre sterling","Yen","Nasdaq"],a:3,e:"Le Nasdaq est un indice boursier, pas une monnaie.",s:"Entraînement, Q38"},
{id:"e-39",t:"log",q:"Paul est plus grand que Marc, Marc plus grand que Léa, Léa plus grande que Tom. Qui est le deuxième plus petit ?",o:["Marc","Paul","Tom","Léa"],a:3,e:"Du plus grand au plus petit : Paul, Marc, Léa, Tom.",s:"Entraînement, Q39"},
{id:"e-40",t:"log",q:"Cinq machines fabriquent cinq pièces en cinq minutes. Combien de minutes faut-il à cent machines pour fabriquer cent pièces ?",o:["1","5","20","100"],a:1,e:"Une machine fait une pièce en 5 minutes ; 100 machines font 100 pièces en 5 minutes.",s:"Entraînement, Q40"},
{id:"e-41",t:"ang",q:"Complete: « I have been working here … 2019. »",o:["for","since","during","from"],a:1,e:"Since + point de départ ; for + durée.",s:"Entraînement, Q41"},
{id:"e-42",t:"ang",q:"What does « tax return » mean?",o:["Déclaration fiscale","Remboursement d'impôt","Taux d'imposition","Retour sur investissement"],a:0,e:"Le remboursement se dit « tax refund ».",s:"Entraînement, Q42"},
{id:"e-43",t:"ang",q:"Which sentence is correct?",o:["She don't like coffee.","She doesn't likes coffee.","She doesn't like coffee.","She not like coffee."],a:2,e:"Doesn't + base verbale.",s:"Entraînement, Q43"},
{id:"e-44",t:"ang",q:"« Eventually, the minister agreed. » What does « eventually » mean?",o:["Éventuellement","Immédiatement","Probablement","Finalement"],a:3,e:"Faux ami : « éventuellement » se dit possibly.",s:"Entraînement, Q44"},
{id:"e-45",t:"ang",q:"Complete: « If I … more time, I would study English. »",o:["have","had","will have","would have"],a:1,e:"Conditionnel présent : if + prétérit, puis would + verbe.",s:"Entraînement, Q45"},

// ---------- QCM officiel contrôleur 2026 ----------
{id:"c26-01",t:"num",m:"ctrl",q:"Les opérations suivantes constituent un traitement de données personnelles, sauf une. Laquelle ?",o:["La collecte de coordonnées de prospects via un questionnaire","La création d'une carte de fidélité avec les coordonnées du client","La mise à jour d'un fichier client pour l'envoi d'une commande","La tenue d'un fichier de coordonnées d'entreprises (nom, adresse, standard, courriel générique)"],a:3,e:"Des coordonnées d'entreprise génériques ne permettent pas d'identifier une personne physique : ce ne sont pas des données personnelles.",x:"Une donnée personnelle est toute information se rapportant à une personne physique identifiée ou identifiable, directement ou indirectement (art. 4 du RGPD). Une adresse prenom.nom@entreprise.fr en est une, contrairement à contact@entreprise.fr.",u:["https://www.cnil.fr/fr/identifier-les-donnees-personnelles"],s:"QCM contrôleur 2026, Q1"},
{id:"c26-02",t:"hg",q:"En 2014, l'Assemblée nationale a voté la réduction du nombre de régions métropolitaines de 22 à :",o:["8","10","13","15"],a:2,e:"13 régions métropolitaines depuis le 1er janvier 2016 (loi du 16 janvier 2015).",x:"Sept régions sont nées de fusions (par exemple Grand Est, Nouvelle-Aquitaine, Occitanie) ; six sont restées inchangées, dont la Bretagne, l'Île-de-France et la Corse.",u:["https://www.vie-publique.fr/fiches/19628-quelle-est-la-nouvelle-carte-regionale-issue-de-la-loi-de-janvier-2015","https://fr.wikipedia.org/wiki/Loi_relative_%C3%A0_la_d%C3%A9limitation_des_r%C3%A9gions,_aux_%C3%A9lections_r%C3%A9gionales_et_d%C3%A9partementales_et_modifiant_le_calendrier_%C3%A9lectoral"],s:"QCM contrôleur 2026, Q2"},
{id:"c26-03",t:"hg",q:"Le début du règne de Louis XIV se situe pendant :",o:["L'Antiquité","L'Époque moderne","L'Histoire contemporaine","Le Moyen Âge"],a:1,e:"Louis XIV règne de 1643 à 1715. Époque moderne : 1492 (ou 1453) – 1789.",x:"Roi à 4 ans en 1643, il ne gouverne personnellement qu'à partir de 1661, à la mort de Mazarin. Son règne de 72 ans est le plus long de l'histoire de France.",u:["https://fr.wikipedia.org/wiki/Louis_XIV","https://fr.wikipedia.org/wiki/%C3%89poque_moderne"],s:"QCM contrôleur 2026, Q3"},
{id:"c26-04",t:"hg",q:"Quel est l'apport majeur de la bataille de Marignan ?",o:["La chute de l'Empire romain d'Orient","Le début de la Renaissance française","Le début du siècle des Lumières","Le partage du royaume de Charlemagne"],a:1,e:"1515, début du règne de François Ier, qui fait venir la Renaissance italienne en France.",x:"Victoire de François Ier sur les Suisses alliés du duc de Milan (13 et 14 septembre 1515). Le roi accueillera ensuite Léonard de Vinci, mort à Amboise en 1519.",u:["https://fr.wikipedia.org/wiki/Bataille_de_Marignan"],s:"QCM contrôleur 2026, Q4"},
{id:"c26-05",t:"hg",q:"Qui était le premier président de la République française ?",o:["Louis-Napoléon Bonaparte","Paul Doumer","Félix Faure","Raymond Poincaré"],a:0,e:"Élu au suffrage universel masculin en décembre 1848 (IIe République).",x:"Élu le 10 décembre 1848 avec près de 75 % des voix, il réalise un coup d'État le 2 décembre 1851, puis rétablit l'Empire en 1852 sous le nom de Napoléon III.",u:["https://fr.wikipedia.org/wiki/%C3%89lection_pr%C3%A9sidentielle_fran%C3%A7aise_de_1848","https://fr.wikipedia.org/wiki/Napol%C3%A9on_III"],s:"QCM contrôleur 2026, Q5"},
{id:"c26-06",t:"admin",q:"Quelle institution française est renouvelée par tiers tous les 3 ans ?",o:["L'Assemblée nationale","Le Conseil constitutionnel","Le Conseil d'État","Le Sénat"],a:1,e:"Le Sénat est renouvelé par moitié tous les 3 ans.",x:"Les membres nommés le sont pour 9 ans non renouvelables ; les anciens présidents de la République sont membres de droit. Le Sénat, lui, est renouvelé par moitié tous les 3 ans.",u:["https://www.vie-publique.fr/fiches/19554-quelle-est-la-composition-du-conseil-constitutionnel","https://www.conseil-constitutionnel.fr/le-conseil-constitutionnel/les-membres"],s:"QCM contrôleur 2026, Q6"},
{id:"c26-07",t:"ue",q:"Quelle institution européenne adopte les lois et le budget avec le Parlement européen ?",o:["La Banque centrale européenne","La Commission européenne","Le Conseil de l'Union européenne","La Cour de justice de l'Union européenne"],a:2,e:"Le Conseil de l'UE (les ministres) est co-législateur et co-autorité budgétaire.",x:"À ne pas confondre avec le Conseil européen (chefs d'État ou de gouvernement), qui ne légifère pas. Le Conseil de l'UE se réunit en dix formations, par exemple ECOFIN pour l'économie et les finances.",u:["https://www.vie-publique.fr/fiches/20329-quelle-est-la-fonction-du-conseil-de-lunion-europeenne","https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/council-european-union_fr"],s:"QCM contrôleur 2026, Q7"},
{id:"c26-08",t:"ue",q:"Quel est le principal objectif de la politique monétaire menée dans la zone euro ?",o:["Favoriser les politiques environnementales","La libre circulation des biens et des personnes","Lutter contre la fraude","Maîtriser le taux d'inflation"],a:3,e:"Stabilité des prix : inflation de 2 % à moyen terme (BCE).",x:"Son principal instrument est le pilotage des taux directeurs. La BCE est indépendante : elle ne peut recevoir d'instructions des gouvernements ni financer directement les États (art. 123 et 130 TFUE).",u:["https://www.ecb.europa.eu/mopo/strategy/html/index.fr.html","https://www.vie-publique.fr/fiches/21800-quel-est-le-role-de-la-banque-centrale-europeenne-bce"],s:"QCM contrôleur 2026, Q8"},
{id:"c26-09",t:"fr",q:"Quelle phrase comporte un complément circonstanciel de temps ?",o:["Il me reste deux minutes.","Je suis toujours de mauvaise humeur le matin.","La journée est ensoleillée.","La journée était interminable."],a:1,e:"« le matin » : déplaçable et supprimable, il indique quand.",s:"QCM contrôleur 2026, Q9"},
{id:"c26-10",t:"fr",q:"Quelle phrase contient une faute d'orthographe ?",o:["Ils ont acheté une nouvelle voiture.","Ils ont beaucoup étudié pour l'examen.","Ils ont tous acceptés l'invitation.","Ils sont arrivés en retard."],a:2,e:"Avec avoir et sans COD placé avant : « ont tous accepté ».",s:"QCM contrôleur 2026, Q10"},
{id:"c26-11",t:"fr",q:"Dans quelle phrase le participe passé est-il correctement accordé ?",o:["Les lettres qu'il a écrit sont sur la table.","Les lettres qu'il a écrite sont sur la table.","Les lettres qu'il a écrites sont sur la table.","Les lettres qu'il a écrits sont sur la table."],a:2,e:"COD « lettres » (féminin pluriel) placé avant l'auxiliaire avoir : écrites.",s:"QCM contrôleur 2026, Q11"},
{id:"c26-12",t:"fr",q:"Combien de fautes contient : « Elle avait désormais trois milles cinq cents quarante euro sur son conte bancaire » ?",o:["1 faute","2 fautes","3 fautes","4 fautes"],a:3,e:"mille (invariable), cent (suivi d'un nombre), euros, compte.",x:"Grille officielle : 4 fautes. L'arrêté du 28 décembre 1976 tolère pourtant « cinq cents quarante », ce qui ramènerait le décompte à 3 : au concours, raisonne avec la règle classique.",s:"QCM contrôleur 2026, Q12"},
{id:"c26-13",t:"fr",q:"Quelle est la bonne orthographe ?",o:["l'impact environemental","l'impact environementtal","l'impact environemmental","l'impact environnemental"],a:3,e:"Environnement → environnemental (deux n, un m).",s:"QCM contrôleur 2026, Q13"},
{id:"c26-14",t:"fr",q:"Qu'est-ce qu'une chimère ?",o:["Un projet ambitieux","Un projet coûteux","Un projet performant","Un projet séduisant mais irréalisable"],a:3,e:"Chimère : rêve, illusion.",s:"QCM contrôleur 2026, Q14"},
{id:"c26-15",t:"fr",q:"Quel est l'antonyme de « prolifique » ?",o:["Abondant","Créatif","Prospère","Stérile"],a:3,e:"Prolifique = qui produit beaucoup ; contraire : stérile.",s:"QCM contrôleur 2026, Q15"},
{id:"c26-16",t:"fr",q:"Quelle est la définition de « déontologie » ?",o:["Avoir une aisance à l'oral","Ensemble des règles et des devoirs régissant une profession","Faire preuve de civisme","Faire preuve de courage"],a:1,e:"Déontologie : devoirs professionnels.",s:"QCM contrôleur 2026, Q16"},
{id:"c26-17",t:"math",q:"Un moteur tourne à 20 tours par seconde. Combien de tours effectue-t-il en 1 minute 30 secondes ?",o:["26","30","1 200","1 800"],a:3,e:"90 s × 20 = 1 800 tours.",s:"QCM contrôleur 2026, Q17"},
{id:"c26-18",t:"math",q:"Un train part à 10 h pour un terminus situé à 50 km, arrivée prévue à 11 h. Il arrive avec 36 minutes de retard. Quelle a été sa vitesse moyenne ?",o:["25 km/h","31,25 km/h","50 km/h","61,25 km/h"],a:1,e:"Durée : 1 h 36 = 1,6 h. 50 / 1,6 = 31,25 km/h.",s:"QCM contrôleur 2026, Q18"},
{id:"c26-19",t:"math",q:"Un camion avec remorque mesure 40 mètres. Combien mesure son modèle réduit à l'échelle 1/25 000 ?",o:["0,16 centimètre","0,16 millimètre","16 centimètres","16 millimètres"],a:0,e:"4 000 cm / 25 000 = 0,16 cm (1,6 mm).",s:"QCM contrôleur 2026, Q19"},
{id:"c26-20",t:"math",q:"Une commerçante achète 80 carnets à 3 € et prévoit de les revendre 4,50 €. Elle en vend 65, puis baisse le prix des restants de 40 % et écoule tout. Quel est son bénéfice ?",o:["79,50 €","93,00 €","120,00 €","333,00 €"],a:1,e:"65 × 4,50 = 292,50 ; 15 × 2,70 = 40,50 ; recette 333 € ; coût 240 € ; bénéfice 93 €.",s:"QCM contrôleur 2026, Q20"},
{id:"c26-21",t:"math",q:"Lequel de ces nombres est premier ?",o:["51","57","61","63"],a:2,e:"51 = 3 × 17 ; 57 = 3 × 19 ; 63 = 7 × 9 ; 61 est premier.",s:"QCM contrôleur 2026, Q21"},
{id:"c26-22",t:"math",q:"Une fonction est strictement croissante (sur un intervalle) si :",o:["sa dérivée est nulle","sa dérivée est positive ou nulle","sa dérivée est strictement négative","sa dérivée est strictement positive"],a:3,e:"Dérivée strictement positive ⇒ strictement croissante.",s:"QCM contrôleur 2026, Q22"},
{id:"c26-23",t:"math",q:"Températures relevées à Lyon sur 7 jours : 23, 20, 24, 19, 22, 23, 20. Quelle est la médiane ?",o:["20","21","22","23"],a:2,e:"Série classée : 19, 20, 20, 22, 23, 23, 24 ; valeur centrale (4e) : 22. (Données du diagramme du sujet.)",s:"QCM contrôleur 2026, Q23 (diagramme mis en texte)"},
{id:"c26-24",t:"math",q:"Un plombier facture 125 € : 80 € de déplacement plus 15 € par heure commencée. Quelle durée a été facturée ?",o:["2 heures","3 heures","4 heures","14 heures"],a:1,e:"(125 − 80) / 15 = 3 heures.",s:"QCM contrôleur 2026, Q24"},
{id:"c26-25",t:"log",m:"ctrl",q:"Le père de la mère du père de votre tante est votre :",o:["arrière-arrière-grand-oncle","arrière-arrière-arrière-grand-père","arrière-arrière-arrière-grand-oncle","arrière-arrière-grand-père"],a:3,e:"Le père de votre tante est votre grand-père ; sa mère, votre arrière-grand-mère ; son père, votre arrière-arrière-grand-père.",s:"QCM contrôleur 2026, Q25"},
{id:"c26-27",t:"log",m:"ctrl",q:"Mike a terminé ses devoirs avant Paul. Paul et Brian ont tous les deux terminé avant Liam. Qui termine en dernier ?",o:["Brian","Liam","Mike","Paul"],a:1,e:"Mike < Paul < Liam et Brian < Liam : Liam est dernier.",s:"QCM contrôleur 2026, Q27"},
{id:"c26-28",t:"log",m:"ctrl",q:"Quatre livres (bleu, rouge, vert, jaune). Le bleu est à gauche du vert ; le jaune, à droite du vert, ne côtoie pas le rouge ; le rouge n'est pas à une extrémité. Quel est l'ordre de gauche à droite ?",o:["Bleu, rouge, jaune, vert","Bleu, rouge, vert, jaune","Rouge, bleu, jaune, vert","Rouge, bleu, vert, jaune"],a:1,e:"Seul « bleu, rouge, vert, jaune » respecte toutes les contraintes.",s:"QCM contrôleur 2026, Q28"},
{id:"c26-29",t:"log",m:"ctrl",q:"Antoine, Elsa, Ludivine et Héloïse ont 17, 21, 47 et 54 ans et jouent clarinette, flûte, trompette, saxophone. Antoine n'est pas le plus âgé, ne joue pas de flûte et ne travaille pas dans la santé ; Elsa est la plus jeune et ne joue pas du saxophone ; Héloïse est professeur des écoles et a 33 ans de plus que Ludivine ; le trompettiste travaille dans l'informatique ; Ludivine joue de la clarinette et n'est pas au lycée. Quelle affirmation est vraie ?",o:["Antoine a 21 ans, joue du saxophone et travaille dans la santé","Elsa a 17 ans, elle est lycéenne et joue de la flûte","Héloïse a 54 ans, elle est professeur des écoles et joue de la clarinette","Ludivine a 21 ans, travaille dans l'informatique et joue de la trompette"],a:1,e:"Ludivine 21 ans, Héloïse 54, Antoine 47, Elsa 17. Ludivine (clarinette) ne peut être informaticienne ; Antoine n'a pas 21 ans ; la clarinette est à Ludivine. Reste la 2.",s:"QCM contrôleur 2026, Q29"}
);
